import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // 1. Keep amount in admissible domain: must be <= contract balance after seeding
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
        vm.deal(caller, amount + 1 ether);
        // Seed the contract with enough balance for withdrawal
        vm.deal(address(c), amount + 1 ether);

        // 2. Record balances before withdrawal
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = caller.balance;

        // Withdraw as the owner (caller must be owner for this to work; we prank as owner)
        // To make the test general, we assume the caller is the owner
        // Actually, the onlyOwner modifier requires msg.sender == owner.
        // We need to prank as the owner. Let's use the owner from c.owner()
        address contractOwner = c.owner();
        vm.prank(contractOwner);
        c.withdraw(amount);

        // 3. Assert: contract balance decreased by amount (reference behavior)
        // Buggy version sends to owner, so contract balance remains unchanged.
        assertTrue(address(c).balance == contractBalanceBefore - amount);
    }
}

