pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address ownerCandidate) public {
        // Restrict ownerCandidate to be a valid EOA (non-zero), but wide.
        vm.assume(ownerCandidate != address(0));
        // The original contract sets owner to the deployer (this contract).
        // To test the property for any owner-like actor, we prank as the actual owner (this contract) for withdraw.
        // We need the contract to have balance, so we fund it via the fallback.
        // We restrict amount to be within the contract's balance after funding.
        // First, fund the contract by sending amount from this test contract.
        c.fallback{value: amount}();
        // Now the contract has at least `amount` balance.
        // Record previous balances.
        uint256 ownerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;
        // Owner (this contract) calls withdraw.
        vm.prank(address(this));
        c.withdraw(amount);
        uint256 ownerBalanceAfter = address(this).balance;
        uint256 contractBalanceAfter = address(c).balance;
        // The invariant: total ETH of owner + contract remains unchanged after withdraw.
        // Reference (correct) sends amount to owner, so ownerBalanceAfter = ownerBalanceBefore + amount,
        // and contractBalanceAfter = contractBalanceBefore - amount, sum unchanged.
        // Buggy burns amount to address(0), so ownerBalanceAfter = ownerBalanceBefore,
        // contractBalanceAfter = contractBalanceBefore - amount, sum decreases by amount.
        assertTrue(
            ownerBalanceBefore + contractBalanceBefore == ownerBalanceAfter + contractBalanceAfter,
            "Total ETH of owner+contract must be conserved after withdraw"
        );
    }
}

