pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(c));
        vm.assume(amount <= address(this).balance);
        // Deploy adversarial helper that changes owner
        OwnerChanger changer = new OwnerChanger();
        // Fund changer so it can forward value
        vm.deal(address(changer), amount);
        // Make changer call sendMoney on c with itself as target
        changer.attack(address(c), amount);
        // After any sendMoney, the owner must still be the original deployer
        assertTrue(c.owner() == address(this));
    }
}

contract OwnerChanger {
    function attack(address payable c, uint256 amount) external payable {
        // Forward call to sendMoney, which calls back into our receive,
        // where we change ownership by directly writing to C's storage (simulate arbitrary call)
        C(c).sendMoney(address(this), amount);
    }
    receive() external payable {
        // This reverts if caller is C, demonstrating bug where non-owner can trigger sendMoney
        // which then can call arbitrary logic (here we would change owner if we had the slot, but we
        // simply consume the call to show non-owner invocation).
        // For the property: owner must stay same, but since non-owner triggered sendMoney,
        // the callback could potentially modify state. We assert owner unchanged.
        // In reference, onlyOwner prevents this; in bug, it's callable by anyone.
    }
}

