        try c.sendMoney(_target, _value) {
            callSuccess = true;
        } catch {
            callSuccess = false;
        }

        // If the call did not revert, the contract's Ether balance must have decreased by _value
        if (callSuccess) {
            assertEq(address(c).balance, balanceBefore - _value, "Balance should decrease by sent value");
        }
    }
}

